package com.bank.dsa;

import java.util.List;
import java.util.logging.*;

// Runnable demo: list even-numbered accounts up to N for audit.
public class EvenNumbersDemo {
    private static final Logger log = Logger.getLogger(EvenNumbersDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        EvenLister lister = new EvenLister();

        int n = 10;
        List<Integer> evens = lister.evensUpTo(n);
        log.info(() -> "Even account numbers to audit up to " + n + ": " + evens);
    }
}

// ─── Would be in EvenLister.java in a real project ───
class EvenLister {
    // Start at 2, step by 2 -> touches only even numbers (no modulo test needed).
    List<Integer> evensUpTo(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("N must be positive: " + n);
        }
        java.util.List<Integer> result = new java.util.ArrayList<>();
        for (int i = 2; i <= n; i = i + 2) {   // loop while i <= N, step 2
            result.add(i);
        }
        return result;  // n < 2 -> empty list (no evens in range)
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
